        except (json.JSONDecodeError, UnicodeDecodeError):
            return JSONResponse(
                status_code=422,
                content={"error": "请求体必须是合法的 JSON 对象。"},
            )
        try:
            return publish_count(path, payload)
        except ReleaseError as error:
            return JSONResponse(
                status_code=error.status_code,
                content={"error": error.message},
            )

    return application


